(function() {
  var actor = BattleManager.actor();
  if (!actor) return [];
  var cmds = [{
    name: TextManager.attack,
    symbol: "attack",
    enabled: actor.canAttack(),
    iconIndex: 76
  }];
  actor.addedSkillTypes().sort(function(a, b) {
    return a - b;
  }).forEach(function(id) {
    cmds.push({
      name: $dataSystem.skillTypes[id] || '',
      symbol: "skill",
      enabled: true,
      ext: id,
      iconIndex: 79
    });
  });
  cmds.push({
    name: TextManager.guard,
    symbol: "guard",
    enabled: actor.canGuard(),
    iconIndex: 81
  }, {
    name: TextManager.item,
    symbol: "item",
    enabled: true,
    iconIndex: 83
  });
  return cmds;
})()

(function(){
  var actor=BattleManager.actor();
  if(!actor)return[];
  var sid=($ctx&&$ctx.currentSkillStypeId)||1;
  return actor.skills().filter(function(s){return s.stypeId===sid;}).map(function(s){
    var mpCost=actor.skillMpCost(s);
    var tpCost=actor.skillTpCost(s);
    var cost=mpCost>0?'MP:'+mpCost:tpCost>0?'TP:'+tpCost:'';
    return{
      name:s.name,symbol:'skill',enabled:actor.canUse(s),ext:s,
      iconIndex:s.iconIndex,rightText:cost,
      rightTextColorIndex:mpCost>0?23:29
    };
  });
})()

(function(){
  if(typeof $gameParty==='undefined')return[];
  var items=$gameParty.items().filter(function(item){return item.itypeId===1;});
  return items.map(function(item){
    return{
      name:item.name,symbol:'item',
      enabled:$gameParty.canUse(item),
      ext:item,iconIndex:item.iconIndex,
      numberText:$gameParty.numItems(item)
    };
  });
})()
